// Scene: a word pressed into plaster, the light raking across it as the preset cycles
// through the nine bevel characters. props: word, cycleSeconds.
//
// The plaster and grunge textures the drop expects are generated by visuals/make-assets.mjs
// rather than shipped, so this runs with nothing to download.

import { EmbossPlayground } from "./pg-engine";
import { PRESETS, type EmbossParams } from "./params";

export default {
  async mount(host: HTMLElement, props: Record<string, unknown>) {
    let i = 0;
    const params: EmbossParams = { ...PRESETS[1].params };
    const engine = new EmbossPlayground(host, params, {
      word: String(props.word ?? "press"),
      svg: null,
    });
    if (!engine.ok) throw new Error("emboss: WebGL unavailable");
    engine.setFont("-apple-system, 'Helvetica Neue', Arial, sans-serif");

    // Walk the presets so a still card still shows the range of the press.
    const every = Number(props.cycleSeconds ?? 3) * 1000;
    let timer = 0;
    return {
      start: () => {
        timer = window.setInterval(() => {
          i = (i + 1) % PRESETS.length;
          engine.setParams({ ...PRESETS[i].params });
        }, every);
      },
      action: async (name: string) => {
        if (name === "next") {
          i = (i + 1) % PRESETS.length;
          engine.setParams({ ...PRESETS[i].params });
        }
      },
      destroy: () => {
        if (timer) window.clearInterval(timer);
        engine.destroy();
      },
    };
  },
};
